#include <stdint.h>
#include <stdio.h>

// Stack symbols
uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;

uint64_t _trap_stack[256];
uint64_t * const _trap_stack_top = _trap_stack + 256;

// Forward declarations of functions
void __attribute__((noinline, aligned(4096))) target_V();
void __attribute__((noinline, aligned(4096))) evict1();
void __attribute__((noinline, aligned(4096))) evict2();
void __attribute__((noinline, aligned(4096))) evict3();
void __attribute__((noinline, aligned(4096))) evict4();
void __attribute__((noinline, aligned(4096))) evict5();
void __attribute__((noinline, aligned(4096))) evict6();
void __attribute__((noinline, aligned(4096))) evict7();
void __attribute__((noinline, aligned(4096))) evict8();
void __attribute__((noinline, aligned(4096))) evict9();

void __attribute__((noinline)) perform_eviction() {
    evict1();
    evict2();
    evict3();
    evict4();
    evict5();
    evict6();
    evict7();
    evict8();
    evict9();
}

__attribute__((noinline)) uint64_t measure_control_branch(int cond) {
    uint64_t start, end;
    asm volatile (
        "rdcycle %0\n\t"
        "beqz %2, 1f\n\t"
        "nop; nop; nop; nop;\n\t"
        "1:\n\t"
        "rdcycle %1\n\t"
        : "=&r"(start), "=&r"(end)
        : "r"(cond)
        : "memory"
    );
    return end - start;
}

__attribute__((noinline)) uint64_t measure_branch_latency(int train, void (*target)()) {
    uint64_t start, end;
    asm volatile (
        "rdcycle %0\n\t"
        "beqz %2, 1f\n\t"
        "jalr ra, %3, 0\n\t"
        "1:\n\t"
        "rdcycle %1\n\t"
        : "=&r"(start), "=&r"(end)
        : "r"(train), "r"(target)
        : "ra", "memory"
    );
    return end - start;
}

// Trap handler
void __attribute__((naked, aligned(16))) trap_handler() {
    asm volatile (
        "csrw mscratch, %0\n\t"
        "la sp, _trap_stack\n\t"
        "li t0, 2048\n\t"
        "add sp, sp, t0\n\t"
        "csrr t0, mepc\n\t"
        "addi t0, t0, 4\n\t"
        "csrw mepc, t0\n\t"
        "mret\n\t"
        :: "r"(_trap_stack_top)
    );
}

// To host symbol for termination
extern volatile uint64_t tohost;

// Results arrays
uint64_t well_pred[30];
uint64_t mis_pred[30];
uint64_t sfmrs_hit[30];
uint64_t sfmrs_miss[30];

void print_results(const char *name, uint64_t *arr, int len) {
    uint64_t sum = 0;
    uint64_t min = arr[0];
    uint64_t max = arr[0];
    printf("%s raw: [", name);
    for (int i = 0; i < len; i++) {
        sum += arr[i];
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
        printf("%lu", arr[i]);
        if (i < len - 1) {
            printf(", ");
        }
    }
    printf("]\\n");
    printf("%s: avg=%lu, min=%lu, max=%lu\\n", name, sum / len, min, max);
}

int main() {
    // Register trap handler
    asm volatile("csrw mtvec, %0" :: "r"(trap_handler));

    printf("--- Beginning SFMRS Experiment on MegaBoomV3Config ---\\n");

    // Positive Control Run
    for (int t = 0; t < 30; t++) {
        // Train for well-predicted (cond = 0)
        for (int i = 0; i < 20; i++) {
            measure_control_branch(0);
        }
        well_pred[t] = measure_control_branch(0);

        // Train for mispredicted (cond = 0)
        for (int i = 0; i < 20; i++) {
            measure_control_branch(0);
        }
        mis_pred[t] = measure_control_branch(1);
    }

    // SFMRS Experiment Run
    for (int t = 0; t < 30; t++) {
        // Hit Case
        // Train predictor and load target_V into ICache
        for (int i = 0; i < 20; i++) {
            measure_branch_latency(1, target_V);
        }
        sfmrs_hit[t] = measure_branch_latency(0, target_V);

        // Miss Case
        // Train predictor
        for (int i = 0; i < 20; i++) {
            measure_branch_latency(1, target_V);
        }
        // Evict target_V from ICache
        perform_eviction();
        // Measure mispredicted branch (will fetch target_V as a miss)
        sfmrs_miss[t] = measure_branch_latency(0, target_V);
    }

    // Print Results
    print_results("Positive Control (Well Predicted)", well_pred, 30);
    print_results("Positive Control (Mispredicted)", mis_pred, 30);
    print_results("SFMRS (Hit Case)", sfmrs_hit, 30);
    print_results("SFMRS (Miss Case)", sfmrs_miss, 30);

    // End simulation
    printf("--- Experiment Finished ---\\n");
    tohost = 1;
    while (1) {}
    return 0;
}

// Implementations of the aligned functions
void __attribute__((noinline, aligned(4096))) target_V() {
    asm volatile("nop; nop; nop; nop; ret;");
}
void __attribute__((noinline, aligned(4096))) evict1() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict2() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict3() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict4() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict5() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict6() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict7() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict8() { asm volatile("nop; ret;"); }
void __attribute__((noinline, aligned(4096))) evict9() { asm volatile("nop; ret;"); }

// Start function
void __attribute__((naked)) _start() {
    asm volatile(
        "mv sp, %0\\n\\t"
        "jal main\\n\\t"
        :: "r"(_stack_top)
    );
}

