#include <stdint.h>
#include <stdio.h>

// Forward declarations of functions
void __attribute__((noinline, aligned(4096))) target_V();
void __attribute__((noinline)) evict_icache_by_nops() {
    asm volatile (
        ".rept 32768\n\t"
        "nop\n\t"
        ".endr\n\t"
    );
}

// Trap handler
uint64_t _trap_stack[256];
uint64_t * const _trap_stack_top = _trap_stack + 256;

void __attribute__((naked, aligned(16))) trap_handler() {
    asm volatile (
        "la sp, _trap_stack ; "
        "li t0, 2048 ; "
        "add sp, sp, t0 ; "
        "csrw mscratch, sp ; "
        "csrr t0, mepc ; "
        "addi t0, t0, 4 ; "
        "csrw mepc, t0 ; "
        "mret ;"
    );
}

// To host symbol for termination
extern volatile uint64_t tohost;

// Results arrays
uint64_t well_pred[30];
uint64_t mis_pred[30];
uint64_t sfmrs_hit[30];
uint64_t sfmrs_miss[30];

// Pointer chase chains
uint64_t chase_train[6];
uint64_t chase_measure[6];

void init_chase_chains() {
    for (int i = 0; i < 5; i++) {
        chase_train[i] = (uint64_t)&chase_train[i+1];
        chase_measure[i] = (uint64_t)&chase_measure[i+1];
    }
    chase_train[5] = 1;   // Resolves to 1 (beqz NOT taken, falls through to execute)
    chase_measure[5] = 0; // Resolves to 0 (beqz taken, jumps to 1:)
}

uint64_t __attribute__((naked)) measure_control_branch_6(uint64_t *chase_ptr);
uint64_t __attribute__((naked)) measure_branch_latency_6(uint64_t *chase_ptr, void (*target)());

void print_results(const char *name, uint64_t *arr, int len) {
    uint64_t sum = 0;
    uint64_t min = arr[0];
    uint64_t max = arr[0];
    printf("%s raw: [", name);
    for (int i = 0; i < len; i++) {
        sum += arr[i];
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
        printf("%lu", arr[i]);
        if (i < len - 1) {
            printf(", ");
        }
    }
    printf("]\n");
    printf("%s: avg=%lu, min=%lu, max=%lu\n", name, sum / len, min, max);
}

int main() {
    // Register trap handler
    asm volatile("csrw mtvec, %0" :: "r"(trap_handler));

    // Initialize pointer chase chains
    init_chase_chains();

    printf("--- Beginning SFMRS Refined Experiment on MegaBoomV3Config ---\n");

    for (int t = 0; t < 30; t++) {
        // 1. Positive Control: Well-Predicted
        for (int i = 0; i < 20; i++) {
            measure_control_branch_6(chase_measure);
        }
        well_pred[t] = measure_control_branch_6(chase_measure);

        // 2. Positive Control: Mispredicted
        for (int i = 0; i < 20; i++) {
            measure_control_branch_6(chase_measure);
        }
        mis_pred[t] = measure_control_branch_6(chase_train);

        // 3. SFMRS Hit Case
        // Train and ensure target_V is in L1 ICache
        for (int i = 0; i < 20; i++) {
            measure_branch_latency_6(chase_train, target_V);
        }
        sfmrs_hit[t] = measure_branch_latency_6(chase_measure, target_V);

        // 4. SFMRS Miss Case
        // Train
        for (int i = 0; i < 20; i++) {
            measure_branch_latency_6(chase_train, target_V);
        }
        // Force high-density eviction to overcome LFSR and target alignment
        evict_icache_by_nops();
        // Measure speculative fetch redirect stall
        sfmrs_miss[t] = measure_branch_latency_6(chase_measure, target_V);
    }

    // Print Results
    printf("\n=== RESULTS FOR SWEEP LENGTH 6 (REFINED) ===\n");
    print_results("Positive Control (Well Predicted)", well_pred, 30);
    print_results("Positive Control (Mispredicted)", mis_pred, 30);
    print_results("SFMRS (Hit Case)", sfmrs_hit, 30);
    print_results("SFMRS (Miss Case)", sfmrs_miss, 30);

    // End simulation
    printf("\n--- Experiment Finished ---\n");
    tohost = 1;
    while (1) {}
